/// 작업 담당 CLI 가 walwal-harness 명령을 쓸 수 있는지 (명령 · CLI 마다 따로 본다).
/// Claude 는 `.claude/commands/{goal,hot-fix}.md` 를 슬래시 명령으로, Codex 는 `.codex/commands/{goal,hot-fix}.md` 본문과
/// 그 본문이 읽게 하는 CEO 스킬(`.codex/skills/harness-ceo/SKILL.md`)이 있어야 한다.
struct HarnessAvailability: Equatable, Sendable {
    enum Command: String, Sendable {
        case goal
        case hotFix = "hot-fix"
    }

    let agent: JobFiles.Agent
    let command: Command
    /// 명령 파일 (작업 폴더 기준)
    let commandPath: String
    /// 없어서 쓸 수 없게 만든 파일 (작업 폴더 기준)
    let missing: [String]
    /// 쓸 수는 있지만 회사 루프가 막힐 수 있는 제약 (Codex 샌드박스의 작업 폴더 밖 쓰기 · 네트워크). 카드에 함께 보인다.
    let limitations: [String]

    var isAvailable: Bool { missing.isEmpty }

    var summary: String {
        isAvailable
            ? "\(agent.displayName) 로 /\(command.rawValue) 를 쓸 수 있어요"
            : "\(agent.displayName) 는 /\(command.rawValue) 를 쓸 수 없어요 (없음: \(missing.joined(separator: ", ")))"
    }

    /// 설계리뷰 · 작업리뷰 프롬프트에 넣는 한 단락 (실행 방식 권고의 근거)
    var promptNote: String {
        guard isAvailable else { return "\(summary) — 실행 방식은 llm 으로 한다." }
        return "\(summary) (`\(commandPath)`) — 실행 방식으로 harness 를 권할 수 있다."
            + (limitations.isEmpty ? "" : " 단, " + limitations.joined(separator: " ") + " 이 제약으로 막힐 일이면 llm 을 권한다.")
    }

    static func check(workspace: URL, agent: JobFiles.Agent, fix: Bool, extraWriteDirs: [String] = []) -> HarnessAvailability {
        let command: Command = fix ? .hotFix : .goal
        let commandPath = "\(agent == .claude ? ".claude" : ".codex")/commands/\(command.rawValue).md"
        var required = [commandPath]
        if agent == .codex { required.append(".codex/skills/harness-ceo/SKILL.md") }
        let missing = required.filter { !FileManager.default.fileExists(atPath: workspace.appending(path: $0).path) }
        var limitations: [String] = []
        if agent == .codex {
            let extra = extraWriteDirs.isEmpty ? "" : " (추가 쓰기 경로: \(extraWriteDirs.joined(separator: ", ")))"
            limitations.append("Codex 작업은 workspace-write 샌드박스라 작업 폴더 밖 쓰기(워커 스킬 설치, 홈 디렉터리의 상태 파일)가 막힐 수 있어요\(extra).")
            limitations.append("네트워크도 막혀 있어 Telegram 알림 · 대시보드 갱신 · 원격 호출이 실패할 수 있어요.")
        }
        return HarnessAvailability(agent: agent, command: command, commandPath: commandPath, missing: missing, limitations: limitations)
    }
}

