    // 창의 명령은 myterm-agent 를 바로 실행하므로 pane_pid 가 곧 결과 파일을 쓰는 에이전트다
    let pids = (Tmux.output(["list-panes", "-t", "=\(claude.tmuxSession):=\(window)", "-F", "#{pane_pid}"]) ?? "")
        .split(separator: "\n").compactMap { pid_t($0) }
    Tmux.killWindow(session: claude.tmuxSession, name: window)
    Task { [weak self] in
        let alive = { pids.contains { kill($0, 0) == 0 } }
        // 창을 닫으면 SIGHUP 으로 곧 끝난다. 5초 넘게 남아 있으면 강제로 끝낸다.
        var waited = 0
        while waited < 50, alive() {
            try? await Task.sleep(for: .milliseconds(100))
            waited += 1
        }
        if alive() {
            for pid in pids where kill(pid, 0) == 0 { kill(pid, SIGKILL) }
            try? await Task.sleep(for: .milliseconds(300))
        }
        guard let self else { return }
        for url in [job.files.result(.plan, 1), job.files.started(.plan, 1), job.files.document(.plan, 1)] {
            try? FileManager.default.removeItem(at: url)
        }
        var meta = job.meta
        meta.design = true
        JobJSON.write(meta, to: job.files.meta)
        migrating.remove(job.id)
        lastError = nil
        refresh(job.id)
        startLoopIfNeeded()
    }
}

/// 가장 최근에 실패한 단계의 파일을 다음 시도 번호로 옮긴다 (지난 작동 기록 · 결과가 새 실행에 덮어써지지 않게)
private func retryFailedStep(_ job: JobSnapshot) throws {
    for round in job.rounds.reversed() {
        let step: JobStep
        if round.plan?.ok == false {
            step = .plan
        } else if round.planReview?.ok == false {
            step = .planReview
        } else if round.work?.ok == false {
            step = .work
        } else if let reviewRun = round.reviewRun, !reviewRun.ok || round.review == nil {
            step = .review
        } else {
            continue
        }
        try job.files.archiveAttempt(step, round.number)
        touch(job.files.followUp(round.number))   // 오래된 지시로 보아 묵히지 않도록
        return
    }
}

